-- Create privacy + terms pages for gaswholesalers.com (bug 049 candidate 2).
-- Hand-authored legal content (no LLM), grounded in the real business:
-- Gas Wholesalers, wholesale gas/fuel supply, gas@contactforsales.com,
-- +44 (0) 7934 524 911 (from sites.phone), England & Wales.
-- Mirrors the concurrent thread's aao/finetuning legal pages and the leopardess
-- reference: page_type=content, build_status=deployed, in_footer, sections
-- ["generic-text-block"], rebuild_policy='owned' (protects from the 001 clobber).
-- Idempotent + collision-guarded: aborts if the pages already exist (another
-- session may create them concurrently).

BEGIN;

DO $BODY$
DECLARE
  v_site  uuid := '5fe15466-4e2e-4ff2-981e-98c1b7074002'; -- gaswholesalers.com
  v_comp  uuid := '8d81e665-3ee0-443d-a873-690268c15fbb'; -- generic-text-block component
  v_group uuid;
  v_priv  uuid;
  v_terms uuid;
  v_existing int;
BEGIN
  -- Collision guard: if another session already created these, stop and re-assess.
  SELECT count(*) INTO v_existing FROM pages
   WHERE site_id = v_site AND name IN ('privacy','terms');
  IF v_existing > 0 THEN
    RAISE EXCEPTION 'gaswholesalers already has % privacy/terms page(s) — another session may be creating them; aborting', v_existing;
  END IF;

  -- 1. legal nav group (idempotent)
  INSERT INTO site_nav_groups (site_id, group_key, group_label, group_type, position)
  VALUES (v_site, 'legal', 'Legal', 'legal', 10)
  ON CONFLICT (site_id, group_key) DO UPDATE SET updated_at = now()
  RETURNING id INTO v_group;

  -- 2. PRIVACY page + component + nav item
  INSERT INTO pages (site_id, name, url, title, page_type, status, build_status,
                     in_header, in_footer, nav_label, nav_order, sections, rebuild_policy, deployed_at)
  VALUES (v_site, 'privacy', '/privacy.html', 'Privacy Policy', 'content', 'active', 'deployed',
          false, true, 'Privacy Policy', 90, '["generic-text-block"]'::jsonb, 'owned', now())
  RETURNING id INTO v_priv;

  INSERT INTO page_components (page_id, component_id, position, slot_name, build_status, content_data, rendered_html)
  VALUES (v_priv, v_comp, 0, 'generic-text-block', 'deployed',
    jsonb_build_object('heading', $h$Privacy Policy$h$, 'content', $c$<p><strong>Last updated: July 2026</strong></p><p>This policy explains what personal data Gas Wholesalers collects, why we collect it, how we store and use it, and what your rights are. It applies to visitors to this website and to anyone who contacts us or does business with us. We have tried to write it in plain English.</p><h2>Who we are</h2><p>Gas Wholesalers is a wholesale supplier of gas and fuel to commercial customers — including fuel forecourts, commercial fleet operators, and industrial facilities. We are based in the United Kingdom. For the purposes of UK data protection law (UK GDPR), Gas Wholesalers is the data controller for personal data collected through this website and in the course of our business. You can contact us at <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a> or on +44 (0) 7934 524 911.</p><h2>What data we collect and why</h2><p><strong>Enquiries and quote requests.</strong> When you contact us through this website, request a quote, or ask about supply terms, we collect the information you provide — typically your name, business name, email address, phone number, and the details of your enquiry, such as fuel type, estimated volumes, and delivery location. We use this to respond to you and to prepare a quotation or supply proposal. The legal basis is our legitimate interest in responding to a request you have initiated and, where we go on to supply you, the performance of a contract.</p><p><strong>Orders and supply records.</strong> If you become a customer, we hold the information needed to fulfil and account for supply — delivery addresses, site details, order history, and billing information. This is processed on the basis of our contract with you and to meet our legal and accounting obligations.</p><p><strong>Email and phone correspondence.</strong> We keep correspondence as part of our business records. We do not add you to marketing lists without your consent.</p><p><strong>Website usage data.</strong> Our website may collect standard server log data — IP addresses, browser type, pages visited, and timestamps — to keep the site secure and to diagnose technical problems. This data is not used to build individual profiles and is not shared with third parties for advertising.</p><h2>How we store your data</h2><p>Data is held on systems with access controls appropriate to its sensitivity. We do not sell, rent, or trade personal data. We do not transfer data outside the UK or EEA without appropriate safeguards in place.</p><h2>Third-party tools</h2><p>We use a small number of standard third-party services to run our business — for example email and calendar services, accounting software, and website hosting. Where any of these processes personal data on our behalf, we take reasonable steps to ensure appropriate data processing agreements are in place. Hosting providers may log IP addresses and request data as part of normal server operation. We will update this section with specific named tools as our tooling is confirmed and reviewed.</p><h2>How long we keep your data</h2><p>Enquiry correspondence is kept for as long as it remains relevant to an active or potential supply relationship, and for a reasonable period afterwards. Order and accounting records are retained for the period required by law. Data that is no longer needed is deleted.</p><h2>Your rights under UK GDPR</h2><p>You have the right to access the personal data we hold about you, to correct inaccuracies, to request deletion, to restrict or object to certain processing, and to request your data in a portable format where applicable. To exercise any of these rights, contact us at <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a>. We will respond within one month and do not charge for reasonable requests.</p><p>If you are not satisfied with how we handle your data, you have the right to lodge a complaint with the Information Commissioner's Office (ICO). Details are available at <a href='https://ico.org.uk' target='_blank' rel='noopener noreferrer'>ico.org.uk</a>.</p><h2>Cookies</h2><p>This website uses only the cookies necessary for it to function. Where we introduce non-essential or analytics cookies, we will seek your consent before setting them. You can control cookies through your browser settings at any time.</p><h2>Changes to this policy</h2><p>We may update this policy from time to time. The date at the top of this page reflects when it was last revised. We will not make material changes without updating that date.</p><h2>Contact us about this policy</h2><p>If you have any questions about this privacy policy or how we handle your data, please get in touch:</p><p>Email: <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a><br>Phone: +44 (0) 7934 524 911</p>$c$),
    $r$<section id="8d81e665-3ee0-443d-a873-690268c15fbb" class="section section--generic">
  <div class="container">
    <h2 class="section__title">Privacy Policy</h2>
    <div class="section__content"><p><strong>Last updated: July 2026</strong></p><p>This policy explains what personal data Gas Wholesalers collects, why we collect it, how we store and use it, and what your rights are. It applies to visitors to this website and to anyone who contacts us or does business with us. We have tried to write it in plain English.</p><h2>Who we are</h2><p>Gas Wholesalers is a wholesale supplier of gas and fuel to commercial customers — including fuel forecourts, commercial fleet operators, and industrial facilities. We are based in the United Kingdom. For the purposes of UK data protection law (UK GDPR), Gas Wholesalers is the data controller for personal data collected through this website and in the course of our business. You can contact us at <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a> or on +44 (0) 7934 524 911.</p><h2>What data we collect and why</h2><p><strong>Enquiries and quote requests.</strong> When you contact us through this website, request a quote, or ask about supply terms, we collect the information you provide — typically your name, business name, email address, phone number, and the details of your enquiry, such as fuel type, estimated volumes, and delivery location. We use this to respond to you and to prepare a quotation or supply proposal. The legal basis is our legitimate interest in responding to a request you have initiated and, where we go on to supply you, the performance of a contract.</p><p><strong>Orders and supply records.</strong> If you become a customer, we hold the information needed to fulfil and account for supply — delivery addresses, site details, order history, and billing information. This is processed on the basis of our contract with you and to meet our legal and accounting obligations.</p><p><strong>Email and phone correspondence.</strong> We keep correspondence as part of our business records. We do not add you to marketing lists without your consent.</p><p><strong>Website usage data.</strong> Our website may collect standard server log data — IP addresses, browser type, pages visited, and timestamps — to keep the site secure and to diagnose technical problems. This data is not used to build individual profiles and is not shared with third parties for advertising.</p><h2>How we store your data</h2><p>Data is held on systems with access controls appropriate to its sensitivity. We do not sell, rent, or trade personal data. We do not transfer data outside the UK or EEA without appropriate safeguards in place.</p><h2>Third-party tools</h2><p>We use a small number of standard third-party services to run our business — for example email and calendar services, accounting software, and website hosting. Where any of these processes personal data on our behalf, we take reasonable steps to ensure appropriate data processing agreements are in place. Hosting providers may log IP addresses and request data as part of normal server operation. We will update this section with specific named tools as our tooling is confirmed and reviewed.</p><h2>How long we keep your data</h2><p>Enquiry correspondence is kept for as long as it remains relevant to an active or potential supply relationship, and for a reasonable period afterwards. Order and accounting records are retained for the period required by law. Data that is no longer needed is deleted.</p><h2>Your rights under UK GDPR</h2><p>You have the right to access the personal data we hold about you, to correct inaccuracies, to request deletion, to restrict or object to certain processing, and to request your data in a portable format where applicable. To exercise any of these rights, contact us at <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a>. We will respond within one month and do not charge for reasonable requests.</p><p>If you are not satisfied with how we handle your data, you have the right to lodge a complaint with the Information Commissioner's Office (ICO). Details are available at <a href='https://ico.org.uk' target='_blank' rel='noopener noreferrer'>ico.org.uk</a>.</p><h2>Cookies</h2><p>This website uses only the cookies necessary for it to function. Where we introduce non-essential or analytics cookies, we will seek your consent before setting them. You can control cookies through your browser settings at any time.</p><h2>Changes to this policy</h2><p>We may update this policy from time to time. The date at the top of this page reflects when it was last revised. We will not make material changes without updating that date.</p><h2>Contact us about this policy</h2><p>If you have any questions about this privacy policy or how we handle your data, please get in touch:</p><p>Email: <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a><br>Phone: +44 (0) 7934 524 911</p></div>
  </div>
</section>$r$);

  INSERT INTO site_nav_items (site_id, group_id, label, url, page_id, item_type, position, status)
  VALUES (v_site, v_group, 'Privacy Policy', '/privacy.html', v_priv, 'page_link', 0, 'active');

  -- 3. TERMS page + component + nav item
  INSERT INTO pages (site_id, name, url, title, page_type, status, build_status,
                     in_header, in_footer, nav_label, nav_order, sections, rebuild_policy, deployed_at)
  VALUES (v_site, 'terms', '/terms.html', 'Terms of Service', 'content', 'active', 'deployed',
          false, true, 'Terms of Service', 91, '["generic-text-block"]'::jsonb, 'owned', now())
  RETURNING id INTO v_terms;

  INSERT INTO page_components (page_id, component_id, position, slot_name, build_status, content_data, rendered_html)
  VALUES (v_terms, v_comp, 0, 'generic-text-block', 'deployed',
    jsonb_build_object('heading', $h$Terms of Service$h$, 'content', $c$<p><strong>Last updated: July 2026</strong></p><p>These terms govern your use of the Gas Wholesalers website. By using this website, you accept these terms. If you do not accept them, please do not use the site.</p><h2>Who we are</h2><p>Gas Wholesalers is a wholesale supplier of gas and fuel to commercial customers, including fuel forecourts, commercial fleets, and industrial facilities. We are based in the United Kingdom. You can contact us at <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a> or on +44 (0) 7934 524 911.</p><h2>Using this website</h2><p>You may use this website for lawful purposes and for your own or your organisation's informational use. You agree not to misuse it — for example by attempting to gain unauthorised access, disrupting its operation, or using it to break the law.</p><h2>Information on this website</h2><p>We take care to keep the information on this website accurate and up to date, but we provide it for general information only. Pricing indications, availability, and supply information shown here are illustrative and do not constitute an offer or a binding quotation. Nothing on this website is professional, legal, financial, or technical advice, and you should not rely on it as such.</p><h2>Interactive tools and calculators</h2><p>This website may provide interactive tools, calculators, and estimators — for example for fuel costs, budgets, or unit conversions. These are provided for general guidance and illustration only. Their results depend on the information you enter and on assumptions built into them, and they may not reflect current market prices or your specific circumstances. They are not a quotation, a price guarantee, or a substitute for professional advice, and we are not liable for decisions made in reliance on their output.</p><h2>Our supply of gas and fuel</h2><p>Any actual supply of gas or fuel is governed by a separate written supply agreement and by the order and delivery terms agreed with each customer. These website terms do not form part of, or vary, any such agreement. Nothing on this website is an offer capable of acceptance or a binding quotation.</p><h2>Intellectual property</h2><p>The content, design, branding, and materials on this website are owned by Gas Wholesalers or our licensors and are protected by intellectual property laws. You may view and print pages for your own reference. You may not reproduce, republish, or commercially exploit our content without our permission.</p><h2>Links to other sites</h2><p>This website may link to third-party websites. We provide those links for convenience and do not control or endorse the content of external sites. We are not responsible for them.</p><h2>No warranties</h2><p>We provide this website on an "as is" and "as available" basis. We do not warrant that it will be uninterrupted, error-free, or free of harmful components, or that any result obtained from it will be accurate or reliable.</p><h2>Limitation of liability</h2><p>To the fullest extent permitted by law, we are not liable for any loss or damage arising from your use of, or inability to use, this website or anything on it, including any interactive tool. Nothing in these terms excludes or limits our liability where it would be unlawful to do so — for example for death or personal injury caused by negligence, or for fraud. Terms relating to the supply of gas and fuel itself, including any liability arising from that supply, are dealt with in the separate supply agreement, not here.</p><h2>Changes to these terms</h2><p>We may update these terms from time to time. The date at the top of this page shows when they were last revised. By continuing to use the website after a change, you accept the revised terms.</p><h2>Governing law</h2><p>These terms are governed by the laws of England and Wales, and any dispute relating to them or to this website is subject to the jurisdiction of the courts of England and Wales.</p><h2>Contact us</h2><p>If you have any questions about these terms, please get in touch:</p><p>Email: <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a><br>Phone: +44 (0) 7934 524 911</p>$c$),
    $r$<section id="8d81e665-3ee0-443d-a873-690268c15fbb" class="section section--generic">
  <div class="container">
    <h2 class="section__title">Terms of Service</h2>
    <div class="section__content"><p><strong>Last updated: July 2026</strong></p><p>These terms govern your use of the Gas Wholesalers website. By using this website, you accept these terms. If you do not accept them, please do not use the site.</p><h2>Who we are</h2><p>Gas Wholesalers is a wholesale supplier of gas and fuel to commercial customers, including fuel forecourts, commercial fleets, and industrial facilities. We are based in the United Kingdom. You can contact us at <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a> or on +44 (0) 7934 524 911.</p><h2>Using this website</h2><p>You may use this website for lawful purposes and for your own or your organisation's informational use. You agree not to misuse it — for example by attempting to gain unauthorised access, disrupting its operation, or using it to break the law.</p><h2>Information on this website</h2><p>We take care to keep the information on this website accurate and up to date, but we provide it for general information only. Pricing indications, availability, and supply information shown here are illustrative and do not constitute an offer or a binding quotation. Nothing on this website is professional, legal, financial, or technical advice, and you should not rely on it as such.</p><h2>Interactive tools and calculators</h2><p>This website may provide interactive tools, calculators, and estimators — for example for fuel costs, budgets, or unit conversions. These are provided for general guidance and illustration only. Their results depend on the information you enter and on assumptions built into them, and they may not reflect current market prices or your specific circumstances. They are not a quotation, a price guarantee, or a substitute for professional advice, and we are not liable for decisions made in reliance on their output.</p><h2>Our supply of gas and fuel</h2><p>Any actual supply of gas or fuel is governed by a separate written supply agreement and by the order and delivery terms agreed with each customer. These website terms do not form part of, or vary, any such agreement. Nothing on this website is an offer capable of acceptance or a binding quotation.</p><h2>Intellectual property</h2><p>The content, design, branding, and materials on this website are owned by Gas Wholesalers or our licensors and are protected by intellectual property laws. You may view and print pages for your own reference. You may not reproduce, republish, or commercially exploit our content without our permission.</p><h2>Links to other sites</h2><p>This website may link to third-party websites. We provide those links for convenience and do not control or endorse the content of external sites. We are not responsible for them.</p><h2>No warranties</h2><p>We provide this website on an "as is" and "as available" basis. We do not warrant that it will be uninterrupted, error-free, or free of harmful components, or that any result obtained from it will be accurate or reliable.</p><h2>Limitation of liability</h2><p>To the fullest extent permitted by law, we are not liable for any loss or damage arising from your use of, or inability to use, this website or anything on it, including any interactive tool. Nothing in these terms excludes or limits our liability where it would be unlawful to do so — for example for death or personal injury caused by negligence, or for fraud. Terms relating to the supply of gas and fuel itself, including any liability arising from that supply, are dealt with in the separate supply agreement, not here.</p><h2>Changes to these terms</h2><p>We may update these terms from time to time. The date at the top of this page shows when they were last revised. By continuing to use the website after a change, you accept the revised terms.</p><h2>Governing law</h2><p>These terms are governed by the laws of England and Wales, and any dispute relating to them or to this website is subject to the jurisdiction of the courts of England and Wales.</p><h2>Contact us</h2><p>If you have any questions about these terms, please get in touch:</p><p>Email: <a href='mailto:gas@contactforsales.com'>gas@contactforsales.com</a><br>Phone: +44 (0) 7934 524 911</p></div>
  </div>
</section>$r$);

  INSERT INTO site_nav_items (site_id, group_id, label, url, page_id, item_type, position, status)
  VALUES (v_site, v_group, 'Terms of Service', '/terms.html', v_terms, 'page_link', 1, 'active');

  RAISE NOTICE 'gaswholesalers legal pages created: privacy=%, terms=%, group=%', v_priv, v_terms, v_group;
END
$BODY$;

COMMIT;
